package dev.ftb.mods.ftbquests;

import com.mojang.brigadier.CommandDispatcher;
import com.mojang.datafixers.util.Either;
import dev.architectury.event.EventResult;
import dev.architectury.event.events.common.*;
import dev.architectury.hooks.level.entity.PlayerHooks;
import dev.ftb.mods.ftbquests.block.QuestBarrierBlock;
import dev.ftb.mods.ftbquests.command.FTBQuestsCommands;
import dev.ftb.mods.ftbquests.events.ClearFileCacheEvent;
import dev.ftb.mods.ftbquests.quest.BaseQuestFile;
import dev.ftb.mods.ftbquests.quest.ServerQuestFile;
import dev.ftb.mods.ftbquests.quest.task.*;
import dev.ftb.mods.ftbquests.registry.ModBlockEntityTypes;
import dev.ftb.mods.ftbquests.registry.ModBlocks;
import dev.ftb.mods.ftbquests.registry.ModDataComponents;
import dev.ftb.mods.ftbquests.registry.ModItems;
import dev.ftb.mods.ftbquests.util.DeferredInventoryDetection;
import dev.ftb.mods.ftbquests.util.FTBQuestsInventoryListener;
import dev.ftb.mods.ftbteams.api.event.PlayerChangedTeamEvent;
import dev.ftb.mods.ftbteams.api.event.PlayerLoggedInAfterTeamEvent;
import dev.ftb.mods.ftbteams.api.event.TeamCreatedEvent;
import dev.ftb.mods.ftbteams.api.event.TeamEvent;
import net.minecraft.commands.CommandBuildContext;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.commands.Commands;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.Container;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.InventoryMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.GameRules;
import net.minecraft.world.level.Level;

import java.util.List;

public enum FTBQuestsEventHandler {
	INSTANCE;

	private List<KillTask> killTasks = null;
	private List<InteractionTask> interactionTasks = null;
	private List<Task> autoSubmitTasks = null;

	void init() {
		LifecycleEvent.SERVER_BEFORE_START.register(this::serverAboutToStart);
		CommandRegistrationEvent.EVENT.register(this::registerCommands);
		LifecycleEvent.SERVER_STARTED.register(this::serverStarted);
		LifecycleEvent.SERVER_STOPPING.register(this::serverStopped);
		LifecycleEvent.SERVER_LEVEL_SAVE.register(this::worldSaved);
		ModDataComponents.register();
		ModBlocks.register();
		ModItems.register();
		ModBlockEntityTypes.register();
		ClearFileCacheEvent.EVENT.register(this::fileCacheClear);
		TeamEvent.PLAYER_LOGGED_IN.register(this::playerLoggedIn);
		TeamEvent.CREATED.register(this::teamCreated);
		TeamEvent.PLAYER_CHANGED.register(this::playerChangedTeam);
		EntityEvent.LIVING_DEATH.register(this::playerKill);
		TickEvent.PLAYER_POST.register(this::playerTick);
		PlayerEvent.CRAFT_ITEM.register(this::itemCrafted);
		PlayerEvent.SMELT_ITEM.register(this::itemSmelted);
		PlayerEvent.PLAYER_CLONE.register(this::cloned);
		PlayerEvent.CHANGE_DIMENSION.register(this::changedDimension);
		PlayerEvent.OPEN_MENU.register(this::containerOpened);
		InteractionEvent.RIGHT_CLICK_BLOCK.register(this::playerInteractBlock);
		InteractionEvent.INTERACT_ENTITY.register(this::playerInteractEntity);
		TickEvent.SERVER_POST.register(DeferredInventoryDetection::tick);
		TickEvent.SERVER_POST.register(QuestBarrierBlock.TeleportTicker::tick);
		TickEvent.SERVER_POST.register(CustomTask.TaskSync::tick);
	}

	private void serverAboutToStart(MinecraftServer server) {
		ServerQuestFile.INSTANCE = new ServerQuestFile(server);
	}

	private void registerCommands(CommandDispatcher<CommandSourceStack> dispatcher, CommandBuildContext ctx, Commands.CommandSelection selection) {
		FTBQuestsCommands.register(dispatcher);
	}

	private void serverStarted(MinecraftServer server) {
		ServerQuestFile.INSTANCE.load();
	}

	private void serverStopped(MinecraftServer server) {
		clearCachedData();

		ServerQuestFile.INSTANCE.saveNow();
		ServerQuestFile.INSTANCE.unload();
		ServerQuestFile.INSTANCE = null;
	}

	private void worldSaved(ServerLevel level) {
		if (ServerQuestFile.INSTANCE != null) {
			ServerQuestFile.INSTANCE.saveNow();
		}
	}

	private void fileCacheClear(BaseQuestFile file) {
		if (file.isServerSide()) {
			clearCachedData();
		}
	}

	private void clearCachedData() {
		killTasks = null;
		interactionTasks = null;
		autoSubmitTasks = null;
	}

	private void playerLoggedIn(PlayerLoggedInAfterTeamEvent event) {
		ServerQuestFile.INSTANCE.playerLoggedIn(event);
	}

	private void teamCreated(TeamCreatedEvent event) {
		ServerQuestFile.INSTANCE.teamCreated(event);
	}

	private void playerChangedTeam(PlayerChangedTeamEvent event) {
		ServerQuestFile.INSTANCE.playerChangedTeam(event);
	}

	private EventResult playerKill(LivingEntity entity, DamageSource source) {
		// `source` should never be null, this is a defensive check against badly behaved mods.
		if (source == null) {
			return EventResult.pass();
		}

		if (source.getEntity() instanceof ServerPlayer player && !PlayerHooks.isFake(player)) {
			if (killTasks == null) {
				killTasks = ServerQuestFile.INSTANCE.collect(KillTask.class);
			}

			if (killTasks.isEmpty()) {
				return EventResult.pass();
			}

			ServerQuestFile.INSTANCE.getTeamData(player).ifPresent(data -> {
				for (KillTask task : killTasks) {
					if (data.getProgress(task) < task.getMaxProgress() && data.canStartTasks(task.getQuest())) {
						task.kill(data, entity);
					}
				}
			});
		}

		return EventResult.pass();
	}

	private EventResult playerInteractBlock(Player player, InteractionHand interactionHand, BlockPos blockPos, Direction direction) {
		return playerInteract(player, Either.left(blockPos));
	}

	private EventResult playerInteractEntity(Player player, Entity entity, InteractionHand interactionHand) {
		return playerInteract(player, Either.right(entity));
	}

	private EventResult playerInteract(Player player, Either<BlockPos, Entity> either) {
		if (!player.level().isClientSide() && !PlayerHooks.isFake(player)) {
			if (interactionTasks == null) {
				interactionTasks = ServerQuestFile.INSTANCE.collect(InteractionTask.class);
			}
			if (interactionTasks.isEmpty()) {
				return EventResult.pass();
			}
			ServerQuestFile.INSTANCE.getTeamData(player).ifPresent(data -> {
				for (var task : interactionTasks) {
					if (data.getProgress(task) < task.getMaxProgress() && data.canStartTasks(task.getQuest())) {
						either.ifLeft(pos -> task.interacted(data, player.level(), pos))
								.ifRight(entity -> task.interacted(data, entity)
						);
					}
				}
			});
		}

		return EventResult.pass();
	}

	private void playerTick(Player player) {
		ServerQuestFile file = ServerQuestFile.INSTANCE;

		if (player instanceof ServerPlayer serverPlayer && file != null && !PlayerHooks.isFake(player)) {
			if (autoSubmitTasks == null) {
				autoSubmitTasks = file.collect(Task.class, t -> t.autoSubmitOnPlayerTick() > 0);
			}

			// Don't be deceived, it's somehow possible to be null here
			if (autoSubmitTasks == null || autoSubmitTasks.isEmpty()) {
				return;
			}

			file.getTeamData(player).ifPresent(data -> {
				long now = player.level().getGameTime();

				file.withPlayerContext(serverPlayer, () -> {
					for (Task task : autoSubmitTasks) {
						long interval = task.autoSubmitOnPlayerTick();
						if (interval > 0L && now % interval == 0L) {
							if (!data.isCompleted(task) && data.canStartTasks(task.getQuest())) {
								task.submitTask(data, serverPlayer);
							}
						}
					}
				});
			});
		}
	}

	private void itemCrafted(Player player, ItemStack crafted, Container inventory) {
		if (player instanceof ServerPlayer && !crafted.isEmpty()) {
			FTBQuestsInventoryListener.detect((ServerPlayer) player, crafted, 0);
		}
	}

	private void itemSmelted(Player player, ItemStack smelted) {
		if (player instanceof ServerPlayer && !smelted.isEmpty()) {
			FTBQuestsInventoryListener.detect((ServerPlayer) player, smelted, 0);
		}
	}

	private void cloned(ServerPlayer oldPlayer, ServerPlayer newPlayer, boolean wonGame) {
		newPlayer.inventoryMenu.addSlotListener(new FTBQuestsInventoryListener(newPlayer));

		if (wonGame) {
			return;
		}

		if (PlayerHooks.isFake(newPlayer) || newPlayer.level().getGameRules().getBoolean(GameRules.RULE_KEEPINVENTORY)) {
			return;
		}

		if (!ServerQuestFile.INSTANCE.dropBookOnDeath()) {
			for (int i = 0; i < oldPlayer.getInventory().items.size(); i++) {
				ItemStack stack = oldPlayer.getInventory().items.get(i);

				if (stack.getItem() == ModItems.BOOK.get() && newPlayer.addItem(stack)) {
					oldPlayer.getInventory().items.set(i, ItemStack.EMPTY);
				}
			}
		}
	}

	private void changedDimension(ServerPlayer player, ResourceKey<Level> oldLevel, ResourceKey<Level> newLevel) {
		if (!PlayerHooks.isFake(player)) {
			ServerQuestFile file = ServerQuestFile.INSTANCE;
			file.getTeamData(player).ifPresent(data -> {
				if (!data.isLocked()) {
					file.withPlayerContext(player, () -> {
						for (DimensionTask task : file.collect(DimensionTask.class)) {
							if (data.canStartTasks(task.getQuest())) {
								task.submitTask(data, player);
							}
						}
					});
				}
			});
		}
	}

	private void containerOpened(Player player, AbstractContainerMenu menu) {
		if (player instanceof ServerPlayer && !PlayerHooks.isFake(player) && !(menu instanceof InventoryMenu)) {
			menu.addSlotListener(new FTBQuestsInventoryListener((ServerPlayer) player));
		}
	}
}

package dev.ftb.mods.ftbquests.quest.task;

import dev.ftb.mods.ftbquests.quest.Quest;
import dev.ftb.mods.ftbquests.quest.TeamData;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;

public abstract class AbstractBooleanTask extends Task {
	public AbstractBooleanTask(long id, Quest quest) {
		super(id, quest);
	}

	@Override
	public String formatMaxProgress() {
		return "1";
	}

	@Override
	public String formatProgress(TeamData teamData, long progress) {
		return progress >= 1L ? "1" : "0";
	}

	public abstract boolean canSubmit(TeamData teamData, ServerPlayer player);

	@Override
	public void submitTask(TeamData teamData, ServerPlayer player, ItemStack craftedItem) {
		if (!teamData.isCompleted(this) && checkTaskSequence(teamData) && canSubmit(teamData, player)) {
			teamData.setProgress(this, 1L);
		}
	}
}

package dev.ftb.mods.ftbquests.quest.task;

import dev.ftb.mods.ftblibrary.config.ConfigGroup;
import dev.ftb.mods.ftblibrary.config.NameMap;
import dev.ftb.mods.ftblibrary.icon.Icon;
import dev.ftb.mods.ftblibrary.icon.ItemIcon;
import dev.ftb.mods.ftblibrary.util.KnownServerRegistries;
import dev.ftb.mods.ftbquests.quest.Quest;
import dev.ftb.mods.ftbquests.quest.TeamData;
import dev.ftb.mods.ftbquests.util.TextUtils;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.ChatFormatting;
import net.minecraft.advancements.AdvancementHolder;
import net.minecraft.advancements.AdvancementProgress;
import net.minecraft.advancements.CriterionProgress;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;

public class AdvancementTask extends AbstractBooleanTask {
	private ResourceLocation advancement = ResourceLocation.parse("minecraft:story/root");
	private String criterion = "";

	public AdvancementTask(long id, Quest quest) {
		super(id, quest);
	}

	@Override
	public TaskType getType() {
		return TaskTypes.ADVANCEMENT;
	}

	@Override
	public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.writeData(nbt, provider);
		nbt.putString("advancement", advancement.toString());
		nbt.putString("criterion", criterion);
	}

	@Override
	public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.readData(nbt, provider);
		advancement = ResourceLocation.tryParse(nbt.getString("advancement"));
		criterion = nbt.getString("criterion");
	}

	@Override
	public void writeNetData(RegistryFriendlyByteBuf buffer) {
		super.writeNetData(buffer);
		buffer.writeResourceLocation(advancement);
		buffer.writeUtf(criterion, Short.MAX_VALUE);
	}

	@Override
	public void readNetData(RegistryFriendlyByteBuf buffer) {
		super.readNetData(buffer);
		advancement = buffer.readResourceLocation();
		criterion = buffer.readUtf(Short.MAX_VALUE);
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void fillConfigGroup(ConfigGroup config) {
		super.fillConfigGroup(config);

		if (KnownServerRegistries.client != null && !KnownServerRegistries.client.advancements().isEmpty()) {
			var advancements = KnownServerRegistries.client.advancements();
			KnownServerRegistries.AdvancementInfo def = advancements.values().iterator().next();
			config.addEnum("advancement", advancement, v -> advancement = v,
					NameMap.of(def.id(), advancements.keySet().toArray(new ResourceLocation[0]))
							.icon(id -> ItemIcon.getItemIcon(advancements.getOrDefault(id, def).icon()))
							.name(id -> advancements.getOrDefault(id, def).name())
							.create()).setNameKey("ftbquests.task.ftbquests.advancement");
		} else {
			config.addString("advancement", advancement.toString(), v -> advancement = ResourceLocation.tryParse(v), "minecraft:story/root").setNameKey("ftbquests.task.ftbquests.advancement");
		}

		config.addString("criterion", criterion, v -> criterion = v, "");
	}

	@Override
	public Component getAltTitle() {
		KnownServerRegistries reg = getQuestFile().isServerSide() ? KnownServerRegistries.server : KnownServerRegistries.client;

		KnownServerRegistries.AdvancementInfo info = reg == null ?
				null :
				reg.advancements().get(advancement);

		if (info != null && !TextUtils.isComponentEmpty(info.name())) {
			return Component.translatable("ftbquests.task.ftbquests.advancement").append(": ").append(Component.literal("").append(info.name()).withStyle(ChatFormatting.YELLOW));
		}

		return super.getAltTitle();
	}

	@Override
	@Environment(EnvType.CLIENT)
	public Icon getAltIcon() {
		KnownServerRegistries.AdvancementInfo info = KnownServerRegistries.client == null ?
				null :
				KnownServerRegistries.client.advancements().get(advancement);

		if (info != null && !info.icon().isEmpty()) {
			return ItemIcon.getItemIcon(info.icon());
		}

		return super.getAltIcon();
	}

	@Override
	public int autoSubmitOnPlayerTick() {
		return 5;
	}

	@Override
	public boolean canSubmit(TeamData teamData, ServerPlayer player) {
		AdvancementHolder advancementHolder = player.server.getAdvancements().get(advancement);
		if (advancementHolder == null) {
			return false;
		}

		AdvancementProgress progress = player.getAdvancements().getOrStartProgress(advancementHolder);

		if (criterion.isEmpty()) {
			return progress.isDone();
		} else {
			CriterionProgress criterionProgress = progress.getCriterion(criterion);
			return criterionProgress != null && criterionProgress.isDone();
		}
	}
}

package dev.ftb.mods.ftbquests.quest.task;

import dev.ftb.mods.ftblibrary.config.ConfigGroup;
import dev.ftb.mods.ftblibrary.util.StringUtils;
import dev.ftb.mods.ftbquests.client.EnergyTaskClientData;
import dev.ftb.mods.ftbquests.quest.Quest;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;

public abstract class EnergyTask extends Task implements ISingleLongValueTask {
	private long value = 1000L;
	private long maxInput = 1000L;

	public EnergyTask(long id, Quest quest) {
		super(id, quest);
	}

	@Override
	public long getMaxProgress() {
		return value;
	}

	@Override
	public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.writeData(nbt, provider);
		nbt.putLong("value", value);

		if (maxInput > 0L) {
			nbt.putLong("max_input", maxInput);
		}
	}

	@Override
	public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.readData(nbt, provider);
		value = nbt.getLong("value");

		if (value < 1L) {
			value = 1L;
		}

		maxInput = nbt.getLong("max_input");
	}

	@Override
	public void writeNetData(RegistryFriendlyByteBuf buffer) {
		super.writeNetData(buffer);
		buffer.writeVarLong(value);
		buffer.writeVarLong(maxInput);
	}

	@Override
	public void readNetData(RegistryFriendlyByteBuf buffer) {
		super.readNetData(buffer);
		value = buffer.readVarLong();
		maxInput = buffer.readVarLong();
	}

	public long getValue() {
		return value;
	}

	@Override
	public void setValue(long v) {
		value = v;
	}

	@Override
	public MutableComponent getAltTitle() {
		return Component.literal(StringUtils.formatDouble(value, true));
	}

	@Override
	public boolean consumesResources() {
		return true;
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void fillConfigGroup(ConfigGroup config) {
		super.fillConfigGroup(config);
		config.addLong("value", value, v -> value = v, 1000L, 1L, Long.MAX_VALUE);
		config.addLong("max_input", maxInput, v -> maxInput = v, 1000L, 0L, Integer.MAX_VALUE).setNameKey("ftbquests.task.max_input");
	}

	public abstract EnergyTaskClientData getClientData();

	public long getMaxInput() {
		return maxInput;
	}
}

package dev.ftb.mods.ftbquests.quest.task;

import dev.architectury.registry.registries.RegistrarManager;
import dev.ftb.mods.ftblibrary.config.ConfigGroup;
import dev.ftb.mods.ftblibrary.config.NameMap;
import dev.ftb.mods.ftblibrary.ui.Button;
import dev.ftb.mods.ftbquests.quest.Quest;
import dev.ftb.mods.ftbquests.quest.TeamData;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.ChatFormatting;
import net.minecraft.commands.arguments.blocks.BlockInput;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.tags.TagKey;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.pattern.BlockInWorld;

public class InteractionTask extends Task {
    private InteractionType interactionType;
    private String toInteract;

    public InteractionTask(long id, Quest quest) {
        super(id, quest);

        interactionType = InteractionType.BLOCK;
        toInteract = "minecraft:dirt";
    }

    public void setToInteract(InteractionType interactionType, String toInteract) {
        this.interactionType = interactionType;
        this.toInteract = toInteract;
    }

    @Override
    public TaskType getType() {
        return TaskTypes.INTERACTION;
    }

    @Override
    public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
        super.readData(nbt, provider);

        interactionType = InteractionType.NAME_MAP.get(nbt.getString("interaction_type"));
        toInteract = nbt.getString("to_interact");
    }

    @Override
    public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
        super.writeData(nbt, provider);

        nbt.putString("interaction_type", InteractionType.NAME_MAP.getName(interactionType));
        nbt.putString("to_interact", toInteract);
    }

    @Override
    public void writeNetData(RegistryFriendlyByteBuf buffer) {
        super.writeNetData(buffer);

        buffer.writeEnum(interactionType);
        buffer.writeUtf(toInteract);
    }

    @Override
    public void readNetData(RegistryFriendlyByteBuf buffer) {
        super.readNetData(buffer);

        interactionType = buffer.readEnum(InteractionType.class);
        toInteract = buffer.readUtf();
    }

    @Override
    public void fillConfigGroup(ConfigGroup config) {
        super.fillConfigGroup(config);

        config.addEnum("type", interactionType, v -> interactionType = v, InteractionType.NAME_MAP);
        config.addString("match", toInteract, v -> toInteract = v, "minecraft:dirt");
    }

    @Override
    public Component getAltTitle() {
        return Component.translatable("ftbquests.task.ftbquests.interaction").append(": ")
                .append(Component.literal(toInteract).withStyle(ChatFormatting.DARK_GREEN));
    }

    @Override
    @Environment(EnvType.CLIENT)
    public void onButtonClicked(Button button, boolean canClick) {
    }

    @Override
    public boolean checkOnLogin() {
        return false;
    }

    public void interacted(TeamData data, Level level, BlockPos pos) {
        if (data.isCompleted(this)) {
            return;
        }

        BlockInWorld blockInWorld = new BlockInWorld(level, pos, false);
        BlockState blockState = level.getBlockState(pos);

        boolean matched = switch (interactionType) {
            case BLOCK ->
                    String.valueOf(RegistrarManager.getId(blockState.getBlock(), Registries.BLOCK)).equals(toInteract);
            case BLOCK_TAG ->
                    ObservationTask.asTagRL(toInteract)
                            .map(rl -> blockState.is(TagKey.create(Registries.BLOCK, rl)))
                            .orElse(false);
            case BLOCK_STATE -> {
                BlockInput stateMatch = ObservationTask.tryMatchBlock(toInteract, false);
                yield stateMatch != null && stateMatch.test(blockInWorld);
            }
            default -> false;
        };
        if (matched) {
            data.addProgress(this, 1L);
        }
    }

    public void interacted(TeamData data, Entity entity) {
        if (data.isCompleted(this)) {
            return;
        }

        boolean matched = switch (interactionType) {
            case ENTITY_TYPE ->
                    ObservationTask.tryMatchEntity(toInteract, entity);
            case ENTITY_TYPE_TAG ->
                    ObservationTask.asTagRL(toInteract)
                            .map(rl -> entity.getType().is(TagKey.create(Registries.ENTITY_TYPE, rl)))
                            .orElse(false);
            default -> false;
        };
        if (matched) {
            data.addProgress(this, 1L);
        }
    }

    public enum InteractionType {
        BLOCK,
        BLOCK_TAG,
        BLOCK_STATE,
        ENTITY_TYPE,
        ENTITY_TYPE_TAG;

        public static final NameMap<InteractionType> NAME_MAP = NameMap.of(BLOCK, values()).id(v -> v.name().toLowerCase()).create();
    }
}

package dev.ftb.mods.ftbquests.quest.task;

import dev.architectury.registry.registries.RegistrarManager;
import dev.ftb.mods.ftblibrary.config.ConfigGroup;
import dev.ftb.mods.ftblibrary.config.NameMap;
import dev.ftb.mods.ftblibrary.icon.Icon;
import dev.ftb.mods.ftblibrary.icon.IconAnimation;
import dev.ftb.mods.ftblibrary.icon.Icons;
import dev.ftb.mods.ftblibrary.icon.ItemIcon;
import dev.ftb.mods.ftblibrary.ui.Button;
import dev.ftb.mods.ftblibrary.util.Lazy;
import dev.ftb.mods.ftbquests.FTBQuests;
import dev.ftb.mods.ftbquests.client.FTBQuestsClient;
import dev.ftb.mods.ftbquests.quest.Quest;
import dev.ftb.mods.ftbquests.quest.TeamData;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.ChatFormatting;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.tags.TagKey;
