import net.minecraft.world.level.block.state.pattern.BlockInWorld;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.EntityHitResult;
import net.minecraft.world.phys.HitResult;

import java.util.Optional;

public class ObservationTask extends AbstractBooleanTask {
	private long timer;
	private ObserveType observeType;
	private String toObserve;

	public ObservationTask(long id, Quest quest) {
		super(id, quest);

		timer = 0L;
		observeType = ObserveType.BLOCK;
		toObserve = "minecraft:dirt";
	}

	public void setToObserve(String toObserve) {
		this.toObserve = toObserve;
	}

	public long getTimer() {
		return timer;
	}

	@Override
	public TaskType getType() {
		return TaskTypes.OBSERVATION;
	}

	@Override
	public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.writeData(nbt, provider);
		nbt.putLong("timer", timer);
		nbt.putString("observation_type", ObserveType.NAME_MAP.getName(observeType));
		nbt.putInt("observe_type", observeType.ordinal());
		nbt.putString("to_observe", toObserve);
	}

	@Override
	public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.readData(nbt, provider);
		timer = nbt.getLong("timer");
		if (nbt.contains("observe_type")) {
			// legacy - remove in 26.1
			observeType = ObserveType.values()[nbt.getInt("observe_type")];
		} else {
			observeType = ObserveType.NAME_MAP.get(nbt.getString("observation_type"));
		}
		toObserve = nbt.getString("to_observe");
	}

	@Override
	public void writeNetData(RegistryFriendlyByteBuf buffer) {
		super.writeNetData(buffer);
		buffer.writeVarLong(timer);
		buffer.writeEnum(observeType);
		buffer.writeUtf(toObserve);
	}

	@Override
	public void readNetData(RegistryFriendlyByteBuf buffer) {
		super.readNetData(buffer);
		timer = buffer.readVarLong();
		observeType = buffer.readEnum(ObserveType.class);
		toObserve = buffer.readUtf(Short.MAX_VALUE);
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void fillConfigGroup(ConfigGroup config) {
		super.fillConfigGroup(config);
		config.addLong("timer", timer, v -> timer = v, 0L, 0L, 1200L);
		config.addEnum("observe_type", observeType, v -> observeType = v, ObserveType.NAME_MAP);
		config.addString("to_observe", toObserve, v -> toObserve = v, "minecraft:dirt");
	}

	@Override
	public Component getAltTitle() {
		return Component.translatable("ftbquests.task.ftbquests.observation").append(": ")
				.append(Component.literal(toObserve).withStyle(ChatFormatting.DARK_GREEN));
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void onButtonClicked(Button button, boolean canClick) {
	}

	@Override
	public boolean canSubmit(TeamData teamData, ServerPlayer player) {
		return true;
	}

	@Override
	public boolean checkOnLogin() {
		return false;
	}

	public boolean observe(Player player, HitResult result) {
		if (toObserve.isEmpty()) {
			return false;
		}

		if (result instanceof BlockHitResult blockResult) {
			BlockInWorld blockInWorld = new BlockInWorld(player.level(), blockResult.getBlockPos(), false);

			BlockState state = blockInWorld.getState();
			if (state == null) {
				return false;
			}

			Block block = state.getBlock();
			BlockEntity blockEntity = blockInWorld.getEntity();

			switch (observeType) {
				case BLOCK -> {
					return String.valueOf(RegistrarManager.getId(block, Registries.BLOCK)).equals(toObserve);
				}
				case BLOCK_TAG -> {
					return asTagRL(toObserve)
							.map(rl -> state.is(TagKey.create(Registries.BLOCK, rl)))
							.orElse(false);
				}
				case BLOCK_STATE -> {
					BlockInput stateMatch = tryMatchBlock(toObserve, false);
					return stateMatch != null && stateMatch.test(blockInWorld);
				}
				case BLOCK_ENTITY -> {
					BlockInput stateNbtMatch = tryMatchBlock(toObserve, true);
					return stateNbtMatch != null && stateNbtMatch.test(blockInWorld);
				}
				case BLOCK_ENTITY_TYPE -> {
					return blockEntity != null && toObserve.equals(String.valueOf(RegistrarManager.getId(blockEntity.getType(), Registries.BLOCK_ENTITY_TYPE)));
				}
				default -> {
					return false;
				}
			}
		} else if (result instanceof EntityHitResult entityResult) {
			if (observeType == ObserveType.ENTITY_TYPE) {
				return tryMatchEntity(toObserve, entityResult.getEntity());
			} else if (observeType == ObserveType.ENTITY_TYPE_TAG) {
				return asTagRL(toObserve)
						.map(rl -> entityResult.getEntity().getType().is(TagKey.create(Registries.ENTITY_TYPE, rl)))
						.orElse(false);
			}
		}

		return false;
	}

    static boolean tryMatchEntity(String matchAgainst, Entity entity) {
		ResourceLocation entityType = RegistrarManager.getId(entity.getType(), Registries.ENTITY_TYPE);
		if (entityType == null) return false;

		int nbtStart = matchAgainst.indexOf('{');
		int nbtEnd = nbtStart > 0 ? matchAgainst.indexOf('}', nbtStart) : -1;

		String entityId = nbtStart < 0 ? matchAgainst : matchAgainst.substring(0, nbtStart);
		String nbtFilter = nbtStart > 0 && nbtEnd > nbtStart ? matchAgainst.substring(nbtStart, nbtEnd + 1) : "";

		return entityType.toString().equals(entityId) && matchEntityNBT(entity, nbtFilter);
    }

	static boolean matchEntityNBT(Entity entity, String nbtFilter) {
        if (nbtFilter.isEmpty()) return true;
		if (!nbtFilter.startsWith("{")) {
			nbtFilter = "{" + nbtFilter + "}";
		}

		try {
			var filterTag = TagParser.parseTag(nbtFilter);
			CompoundTag entityTag = Util.make(new CompoundTag(), entity::saveWithoutId);
			return NbtUtils.compareNbt(filterTag, entityTag, true);
		} catch (CommandSyntaxException e) {
			return false;
		}
    }

	static Optional<ResourceLocation> asTagRL(String str) {
		try {
			return Optional.ofNullable(ResourceLocation.tryParse(str.startsWith("#") ? str.substring(1) : str));
		} catch (ResourceLocationException e) {
			return Optional.empty();
		}
	}

	static BlockInput tryMatchBlock(String matchAgainst, boolean parseNbt) {
		try {
			BlockStateParser.BlockResult blockStateParser = BlockStateParser.parseForBlock(BuiltInRegistries.BLOCK.asLookup(), new StringReader(matchAgainst), parseNbt);
			return new BlockInput(blockStateParser.blockState(), blockStateParser.properties().keySet(), parseNbt ? blockStateParser.nbt() : null);
		} catch (Exception ex) {
			return null;
		}
	}

	enum ObserveType {
		BLOCK,
		BLOCK_TAG,
		BLOCK_STATE,
		BLOCK_ENTITY,
		BLOCK_ENTITY_TYPE,
		ENTITY_TYPE,
		ENTITY_TYPE_TAG;

		public static final NameMap<ObserveType> NAME_MAP = NameMap.of(BLOCK, values()).id(v -> v.name().toLowerCase()).create();
	}
}

package dev.ftb.mods.ftbquests.quest.task;

import dev.ftb.mods.ftblibrary.config.ConfigGroup;
import dev.ftb.mods.ftblibrary.config.NameMap;
import dev.ftb.mods.ftbquests.quest.Quest;
import dev.ftb.mods.ftbquests.quest.TeamData;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.stats.Stats;
import net.minecraft.world.item.ItemStack;

import java.util.ArrayList;
import java.util.List;

public class StatTask extends Task {
	private ResourceLocation stat;
	private int value = 1;

	public StatTask(long id, Quest quest) {
		super(id, quest);
		stat = Stats.MOB_KILLS;
	}

	@Override
	public TaskType getType() {
		return TaskTypes.STAT;
	}

	@Override
	public long getMaxProgress() {
		return value;
	}

	@Override
	public String formatMaxProgress() {
		return Integer.toString(value);
	}

	@Override
	public String formatProgress(TeamData teamData, long progress) {
		return Long.toUnsignedString(progress);
	}

	@Override
	public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.writeData(nbt, provider);
		nbt.putString("stat", stat.toString());
		nbt.putInt("value", value);
	}

	@Override
	public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.readData(nbt, provider);
		stat = ResourceLocation.tryParse(nbt.getString("stat"));
		value = nbt.getInt("value");
	}

	@Override
	public void writeNetData(RegistryFriendlyByteBuf buffer) {
		super.writeNetData(buffer);
		buffer.writeResourceLocation(stat);
		buffer.writeVarInt(value);
	}

	@Override
	public void readNetData(RegistryFriendlyByteBuf buffer) {
		super.readNetData(buffer);
		stat = buffer.readResourceLocation();
		value = buffer.readVarInt();
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void fillConfigGroup(ConfigGroup config) {
		super.fillConfigGroup(config);

		List<ResourceLocation> list = new ArrayList<>();
		Stats.CUSTOM.iterator().forEachRemaining(s -> list.add(s.getValue()));
		config.addEnum("stat", stat, v -> stat = v, NameMap.of(Stats.MOB_KILLS, list).name(v -> Component.translatable("stat." + v.getNamespace() + "." + v.getPath())).create());
		config.addInt("value", value, v -> value = v, 1, 1, Integer.MAX_VALUE);
	}

	@Override
	public MutableComponent getAltTitle() {
		return Component.translatable("stat." + stat.getNamespace() + "." + stat.getPath());
	}

	@Override
	public int autoSubmitOnPlayerTick() {
		return 3;
	}

	@Override
	public void submitTask(TeamData teamData, ServerPlayer player, ItemStack craftedItem) {
		if (teamData.isCompleted(this) || !checkTaskSequence(teamData)) {
			return;
		}

		ResourceLocation statId = BuiltInRegistries.CUSTOM_STAT.get(stat);

		// workaround for a bug where mods might register a modded stat in the vanilla namespace
		//  https://github.com/FTBTeam/FTB-Mods-Issues/issues/724
		if (statId == null) statId = BuiltInRegistries.CUSTOM_STAT.get(ResourceLocation.tryParse(stat.getPath()));

		if (statId != null) {
			// could be null, if someone brought an FTB Quests save from a different world and the stat's missing here
			int set = Math.min(value, player.getStats().getValue(Stats.CUSTOM.get(statId)));
			if (set > teamData.getProgress(this)) {
				teamData.setProgress(this, set);
			}
		}
	}
}

package dev.ftb.mods.ftbquests.quest.task;

import com.mojang.datafixers.util.Either;
import dev.architectury.networking.NetworkManager;
import dev.ftb.mods.ftblibrary.config.ConfigGroup;
import dev.ftb.mods.ftblibrary.config.NameMap;
import dev.ftb.mods.ftbquests.net.SyncStructuresRequestMessage;
import dev.ftb.mods.ftbquests.quest.Quest;
import dev.ftb.mods.ftbquests.quest.TeamData;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.ChatFormatting;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.tags.TagKey;
import net.minecraft.world.level.StructureManager;
import net.minecraft.world.level.levelgen.structure.Structure;

import java.util.ArrayList;
import java.util.List;

public class StructureTask extends AbstractBooleanTask {
	private static final ResourceLocation DEFAULT_STRUCTURE = ResourceLocation.withDefaultNamespace("mineshaft");

	private static final List<String> KNOWN_STRUCTURES = new ArrayList<>();

	private Either<ResourceKey<Structure>, TagKey<Structure>> structure;

	public StructureTask(long id, Quest quest) {
		super(id, quest);
		structure = Either.left(ResourceKey.create(Registries.STRUCTURE, DEFAULT_STRUCTURE));
	}

	public static void syncKnownStructureList(List<String> data) {
		// receive structure data from server (structure registry doesn't exist on client)
		KNOWN_STRUCTURES.clear();
		KNOWN_STRUCTURES.addAll(data);
	}

	@Override
	public TaskType getType() {
		return TaskTypes.STRUCTURE;
	}

	@Override
	public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.writeData(nbt, provider);
		nbt.putString("structure", getStructure());
	}

	@Override
	public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.readData(nbt, provider);
		setStructure(nbt.getString("structure"));
	}

	@Override
	public void writeNetData(RegistryFriendlyByteBuf buffer) {
		super.writeNetData(buffer);
		buffer.writeUtf(getStructure());
	}

	@Override
	public void readNetData(RegistryFriendlyByteBuf buffer) {
		super.readNetData(buffer);
		setStructure(buffer.readUtf(1024));
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void fillConfigGroup(ConfigGroup config) {
		super.fillConfigGroup(config);
		if (KNOWN_STRUCTURES.isEmpty()) {
			// should not normally be the case, but as a defensive fallback...
			config.addString("structure", getStructure(), this::setStructure, "minecraft:mineshaft");
		} else {
			config.addEnum("structure", getStructure(), this::setStructure, NameMap.of(DEFAULT_STRUCTURE.toString(), KNOWN_STRUCTURES).create());
		}
	}

	@Override
	public MutableComponent getAltTitle() {
		return Component.translatable("ftbquests.task.ftbquests.structure")
				.append(": ").append(Component.literal(getStructure()).withStyle(ChatFormatting.DARK_GREEN));
	}

	@Override
	public int autoSubmitOnPlayerTick() {
		return 20;
	}

	@Override
	public boolean checkOnLogin() {
		// checking on login can cause server lag: https://github.com/FTBTeam/FTB-Mods-Issues/issues/799
		return false;
	}

	@Override
	public boolean canSubmit(TeamData teamData, ServerPlayer player) {
		if (player.isSpectator()) return false;

		ServerLevel level = (ServerLevel) player.level();
		StructureManager mgr = level.structureManager();
		return structure.map(
				key -> {
					Structure structure = mgr.registryAccess().registryOrThrow(Registries.STRUCTURE).get(key);
					return structure != null && mgr.getStructureWithPieceAt(player.blockPosition(), structure).isValid();
				},
				tag -> mgr.getStructureWithPieceAt(player.blockPosition(), tag).isValid()
		);
	}

	private void setStructure(String resLoc) {
		structure = resLoc.startsWith("#") ?
				Either.right(TagKey.create(Registries.STRUCTURE, safeResourceLocation(resLoc.substring(1), DEFAULT_STRUCTURE))) :
				Either.left(ResourceKey.create(Registries.STRUCTURE, safeResourceLocation(resLoc, DEFAULT_STRUCTURE)));
	}

	private String getStructure() {
		return structure.map(
				key -> key.location().toString(),
				tag -> "#" + tag.location()
		);
	}

	public static void maybeRequestStructureSync() {
		if (KNOWN_STRUCTURES.isEmpty()) {
			NetworkManager.sendToServer(SyncStructuresRequestMessage.INSTANCE);
		}
	}
}

package dev.ftb.mods.ftbquests.quest.task;

import dev.architectury.networking.NetworkManager;
import dev.ftb.mods.ftblibrary.config.ConfigGroup;
