import java.util.EnumSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;

public abstract class Task extends QuestObject {
	private final Quest quest;
	private boolean optionalTask;

	public Task(long id, Quest quest) {
		super(id);

		this.quest = quest;
		optionalTask = false;
	}

	public Quest getQuest() {
		return quest;
	}

	@Override
	public Quest getRelatedQuest() {
		return quest;
	}

	@Override
	public final QuestObjectType getObjectType() {
		return QuestObjectType.TASK;
	}

	@Override
	public final BaseQuestFile getQuestFile() {
		return quest.getChapter().file;
	}

	@Override
	public final Chapter getQuestChapter() {
		return quest.getChapter();
	}

	@Override
	public final long getParentID() {
		return quest.id;
	}

	public abstract TaskType getType();

	@Override
	public final int getRelativeProgressFromChildren(TeamData data) {
		long max = getMaxProgress();

		if (max <= 0L) {
			return 0;
		}

		long progress = data.getProgress(this);

		if (progress <= 0L) {
			return 0;
		} else if (progress >= max) {
			return 100;
		}

		return (int) Math.max(1L, (progress * 100D / (double) max));
	}

	@Override
	public void onStarted(QuestProgressEventData<?> data) {
		data.setStarted(id);
		ObjectStartedEvent.TASK.invoker().act(new ObjectStartedEvent.TaskEvent(data.withObject(this)));
		quest.onStarted(data.withObject(quest));
	}

	@Override
	public final void onCompleted(QuestProgressEventData<?> data) {
		data.setCompleted(id);
		ObjectCompletedEvent.TASK.invoker().act(new ObjectCompletedEvent.TaskEvent(data.withObject(this)));

		boolean questCompleted = quest.isCompletedRaw(data.getTeamData());

		if (quest.getTasks().size() > 1 && !questCompleted && !disableToast) {
			data.notifyPlayers(id);
		}

		if (questCompleted) {
			quest.onCompleted(data.withObject(quest));
		}
	}

	@Override
	public boolean isOptionalForProgression(TeamData teamData) {
		return optionalTask;
	}

	public long getMaxProgress() {
		return 1L;
	}

	public String formatMaxProgress() {
		return StringUtils.formatDouble(getMaxProgress(), true);
	}

	public String formatProgress(TeamData teamData, long progress) {
		return StringUtils.formatDouble(progress, true);
	}

	@Override
	public final void forceProgress(TeamData teamData, ProgressChange progressChange) {
		if (progressChange.isValid()) {
			teamData.setProgress(this, progressChange.shouldReset() ? 0L : getMaxProgress());
		}
	}

	@Override
	public final void deleteSelf() {
		quest.removeTask(this);

		for (TeamData data : quest.getChapter().file.getAllTeamData()) {
			data.resetProgress(this);
		}

		super.deleteSelf();
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void editedFromGUI() {
		QuestScreen gui = ClientUtils.getCurrentGuiAs(QuestScreen.class);
		if (gui != null) {
			gui.refreshChapterPanel();
			gui.refreshQuestPanel();
			gui.refreshViewQuestPanel();
		}
	}

	@Override
	public final void onCreated() {
		super.onCreated();

		quest.addTask(this);

		if (this instanceof CustomTask && getQuestFile().isServerSide()) {
			CustomTaskEvent.EVENT.invoker().act(new CustomTaskEvent((CustomTask) this));
		}
	}

	@Override
	public Component getAltTitle() {
		return getType().getDisplayName();
	}

	@Override
	@Environment(EnvType.CLIENT)
	public Icon getAltIcon() {
		return getType().getIconSupplier();
	}

	@Override
	public final ConfigGroup createSubGroup(ConfigGroup group) {
		TaskType type = getType();
		return group.getOrCreateSubgroup(getObjectType().getId())
				.getOrCreateSubgroup(type.getTypeId().getNamespace())
				.getOrCreateSubgroup(type.getTypeId().getPath());
	}

	@Environment(EnvType.CLIENT)
	public void drawGUI(TeamData teamData, GuiGraphics graphics, int x, int y, int w, int h) {
		getIcon().draw(graphics, x, y, w, h);
	}

	public boolean canInsertItem() {
		return false;
	}

	public boolean consumesResources() {
		return canInsertItem();
	}

	public boolean hideProgressNumbers() {
		return getMaxProgress() <= 1L;
	}

	/**
	 * Called before any progress information is added to the task tooltip
	 * @param list list to append text to
	 * @param teamData the team / player data
	 * @param advanced true for advanced tooltips (when F3+H is in use)
	 */
	@Environment(EnvType.CLIENT)
	public void addMouseOverHeader(TooltipList list, TeamData teamData, boolean advanced) {
		list.add(getTitle());
	}

	/**
	 * Called after any progress information is added to the task tooltip
	 * @param list list to append text to
	 * @param teamData the team / player data
	 */
	@Environment(EnvType.CLIENT)
	public void addMouseOverText(TooltipList list, TeamData teamData) {
	}

	@Environment(EnvType.CLIENT)
	public boolean addTitleInMouseOverText() {
		return true;
	}

	@Environment(EnvType.CLIENT)
	public void onButtonClicked(Button button, boolean canClick) {
		if (canClick && autoSubmitOnPlayerTick() <= 0) {
			button.playClickSound();
			NetworkManager.sendToServer(new SubmitTaskMessage(id));
		}
	}

	public boolean submitItemsOnInventoryChange() {
		return false;
	}

	@Environment(EnvType.CLIENT)
	public Optional<PositionedIngredient> getIngredient(Widget widget) {
		if (addTitleInMouseOverText()) {
			return PositionedIngredient.of(getIcon().getIngredient(), widget);
		}
		return Optional.empty();
	}

	@Override
	public Set<RecipeModHelper.Components> componentsToRefresh() {
		return EnumSet.of(RecipeModHelper.Components.QUESTS);
	}

	@Environment(EnvType.CLIENT)
	public MutableComponent getButtonText() {
		return getMaxProgress() > 1L || consumesResources() ? Component.literal(formatMaxProgress()) : Component.empty();
	}

	public int autoSubmitOnPlayerTick() {
		return 0;
	}

	@Override
	public final boolean cacheProgress() {
		return false;
	}

	public void submitTask(TeamData teamData, ServerPlayer player, ItemStack craftedItem) {
	}

	public final void submitTask(TeamData teamData, ServerPlayer player) {
		submitTask(teamData, player, ItemStack.EMPTY);
	}

	protected final boolean checkTaskSequence(TeamData teamData) {
		if (quest.getRequireSequentialTasks()) {
			List<Task> tasks = quest.getTasksAsList();
			int idx = tasks.indexOf(this);
			return idx >= 0 && (idx == 0 || teamData.isCompleted(tasks.get(idx - 1)));
		} else {
			return true;
		}
	}

	public boolean checkOnLogin() {
		return !consumesResources();
	}

	@Override
	public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.writeData(nbt, provider);
		if (optionalTask) nbt.putBoolean("optional_task", true);
	}

	@Override
	public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.readData(nbt, provider);

		optionalTask = nbt.getBoolean("optional_task");
	}

	@Override
	public void writeNetData(RegistryFriendlyByteBuf buffer) {
		super.writeNetData(buffer);

		buffer.writeBoolean(optionalTask);
	}

	@Override
	public void readNetData(RegistryFriendlyByteBuf buffer) {
		super.readNetData(buffer);

		optionalTask = buffer.readBoolean();
	}

	@Override
	public void fillConfigGroup(ConfigGroup config) {
		super.fillConfigGroup(config);

		config.addBool("optional_task", optionalTask, v -> optionalTask = v, false).setNameKey("ftbquests.quest.misc.optional_task");
	}

	protected ResourceLocation safeResourceLocation(String str, ResourceLocation fallback) {
		var location = ResourceLocation.tryParse(str);
		if (location != null) {
			return location;
		}

		if (getQuestFile().isServerSide()) {
			FTBQuests.LOGGER.warn("Ignoring bad resource location '{}' for task {}", str, id);
		} else {
			FTBQuestsClient.getClientPlayer().displayClientMessage(
					Component.literal("Bad resource location: " + str).withStyle(ChatFormatting.RED), false);
		}

		return fallback;
	}

	@Override
	public CompoundTag makeExtraCreationData() {
		return Util.make(super.makeExtraCreationData(), t -> t.putString("type", getType().getTypeForNBT()));
	}
}

package dev.ftb.mods.ftbquests.quest.task;

import dev.ftb.mods.ftblibrary.config.ConfigGroup;
import dev.ftb.mods.ftbquests.quest.Quest;
import dev.ftb.mods.ftbquests.quest.TeamData;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.ChatFormatting;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;

public class XPTask extends Task implements ISingleLongValueTask {
	private long value = 1L;
	private boolean points = false;

	public XPTask(long id, Quest quest) {
		super(id, quest);
	}

	@Override
	public TaskType getType() {
		return TaskTypes.XP;
	}

	@Override
	public long getMaxProgress() {
		return value;
	}

	@Override
	public String formatMaxProgress() {
		return Long.toUnsignedString(points && value <= Integer.MAX_VALUE ? getLevelForExperience((int) value) : value);
	}

	@Override
	public String formatProgress(TeamData teamData, long progress) {
		return Long.toUnsignedString(points && value <= Integer.MAX_VALUE ? getLevelForExperience((int) progress) : progress);
	}

	@Override
	public void writeData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.writeData(nbt, provider);
		nbt.putLong("value", value);
		nbt.putBoolean("points", points);
	}

	@Override
	public void readData(CompoundTag nbt, HolderLookup.Provider provider) {
		super.readData(nbt, provider);
		value = nbt.getLong("value");
		points = nbt.getBoolean("points");
	}

	@Override
	public void writeNetData(RegistryFriendlyByteBuf buffer) {
		super.writeNetData(buffer);
		buffer.writeVarLong(value);
		buffer.writeBoolean(points);
	}

	@Override
	public void readNetData(RegistryFriendlyByteBuf buffer) {
		super.readNetData(buffer);
		value = buffer.readVarLong();
		points = buffer.readBoolean();
	}

	@Override
	public void setValue(long v) {
		value = v;
	}

	@Override
	@Environment(EnvType.CLIENT)
	public void fillConfigGroup(ConfigGroup config) {
		super.fillConfigGroup(config);
		config.addLong("value", value, v -> value = v, 1L, 1L, Long.MAX_VALUE);
		config.addBool("points", points, v -> points = v, false);
	}

	@Override
	public MutableComponent getAltTitle() {
		return Component.translatable("ftbquests.reward.ftbquests.xp_levels").append(": ").append(Component.literal(formatMaxProgress()).withStyle(ChatFormatting.RED));
	}

	@Override
	public boolean consumesResources() {
		return true;
	}

	public static int getPlayerXP(Player player) {
		return (int) (getExperienceForLevel(player.experienceLevel) + (player.experienceProgress * player.getXpNeededForNextLevel()));
	}

	public static void addPlayerXP(Player player, int amount) {
		int experience = getPlayerXP(player) + amount;
		player.totalExperience = experience;
		player.experienceLevel = getLevelForExperience(experience);
		int expForLevel = getExperienceForLevel(player.experienceLevel);
		player.experienceProgress = (float) (experience - expForLevel) / (float) player.getXpNeededForNextLevel();
	}

	public static int xpBarCap(int level) {
		if (level >= 30) {
			return 112 + (level - 30) * 9;
		}

		if (level >= 15) {
			return 37 + (level - 15) * 5;
		}

		return 7 + level * 2;
	}

	private static int sum(int n, int a0, int d) {
		return n * (2 * a0 + (n - 1) * d) / 2;
	}

	public static int getExperienceForLevel(int level) {
		if (level == 0) {
			return 0;
		}

		if (level <= 15) {
			return sum(level, 7, 2);
		}

		if (level <= 30) {
			return 315 + sum(level - 15, 37, 5);
		}

		return 1395 + sum(level - 30, 112, 9);
	}

	public static int getLevelForExperience(int targetXp) {
		int level = 0;

		while (true) {
			final int xpToNextLevel = xpBarCap(level);

			if (targetXp < xpToNextLevel) {
				return level;
			}

			level++;
			targetXp -= xpToNextLevel;
		}
	}

	@Override
	public void submitTask(TeamData teamData, ServerPlayer player, ItemStack craftedItem) {
		if (!checkTaskSequence(teamData)) {
			return;
		}

		int add = (int) Math.min(points ? getPlayerXP(player) : player.experienceLevel, Math.min(value - teamData.getProgress(this), Integer.MAX_VALUE));

		if (add <= 0) {
			return;
		}

		if (points) {
			addPlayerXP(player, -add);
			player.giveExperienceLevels(0);
		} else {
			player.giveExperienceLevels(-add);
		}

		teamData.addProgress(this, add);
	}
}

package dev.ftb.mods.ftbquests.block.neoforge;

import dev.ftb.mods.ftbquests.block.TaskScreenBlock;
import dev.ftb.mods.ftbquests.block.entity.TaskScreenBlockEntity;
import dev.ftb.mods.ftbquests.integration.item_filtering.ItemMatchingSystem;
import dev.ftb.mods.ftbquests.quest.TeamData;
import dev.ftb.mods.ftbquests.quest.task.FluidTask;
import dev.ftb.mods.ftbquests.quest.task.ItemTask;
import dev.ftb.mods.ftbquests.quest.task.neoforge.ForgeEnergyTask;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Holder;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import net.neoforged.neoforge.energy.IEnergyStorage;
import net.neoforged.neoforge.fluids.FluidStack;
import net.neoforged.neoforge.fluids.capability.IFluidHandler;
import net.neoforged.neoforge.items.IItemHandler;
import org.jetbrains.annotations.NotNull;

public class NeoForgeTaskScreenBlockEntity extends TaskScreenBlockEntity {
    private AABB cachedRenderAABB = null;

    private final TaskItemHandler itemHandler = new TaskItemHandler();
    private final TaskFluidHandler fluidHandler = new TaskFluidHandler();
    private final TaskEnergyHandler energyHandler = new TaskEnergyHandler();

    public NeoForgeTaskScreenBlockEntity(BlockPos blockPos, BlockState blockState) {
        super(blockPos, blockState);
    }

    public IItemHandler getItemHandler() {
        return itemHandler;
    }

    public IFluidHandler getFluidHandler() {
        return fluidHandler;
    }

    public IEnergyStorage getEnergyHandler() {
        return energyHandler;
    }

    public AABB getRenderBoundingBox() {
        if (cachedRenderAABB == null) {
            AABB box = new AABB(getBlockPos());
            if (!(getBlockState().getBlock() instanceof TaskScreenBlock tsb) || tsb.getSize() == 1) {
                cachedRenderAABB = box;
            } else {
                cachedRenderAABB = box.inflate(tsb.getSize());
            }
        }
        return cachedRenderAABB;
    }

    private class TaskItemHandler implements IItemHandler {
        @Override
        public int getSlots() {
            // exposing 2 slots allows us to keep one slot potentially "full" and the other always empty
            // - stops potential inserters thinking the inventory is completely full and not bothering
            return 2;
        }

        @NotNull
        @Override
        public ItemStack getStackInSlot(int slot) {
            // slot 1 is always empty - see above
            return getTask() instanceof ItemTask itemTask && slot == 0 ?
                    itemTask.getItemStack().copyWithCount((int) Math.min(getCachedTeamData().getProgress(itemTask), itemTask.getItemStack().getMaxStackSize())) :
                    ItemStack.EMPTY;
        }

        @NotNull
        @Override
        public ItemStack insertItem(int slot, @NotNull ItemStack stack, boolean simulate) {
            if (slot == 1) {
                TeamData data = getCachedTeamData();
                if (getTask() instanceof ItemTask itemTask && data.canStartTasks(itemTask.getQuest())) {
                    // task.insert() handles testing the item is valid and the task isn't already completed
                    return itemTask.insert(data, stack, simulate);
                }
            }
            return stack;
        }

        @NotNull
        @Override
        public ItemStack extractItem(int slot, int count, boolean simulate) {
            if (slot == 0 && !isInputOnly() && getTask() instanceof ItemTask itemTask && !ItemMatchingSystem.INSTANCE.isItemFilter(itemTask.getItemStack())) {
                TeamData data = getCachedTeamData();
                if (data != null && data.canStartTasks(itemTask.getQuest()) && !data.isCompleted(itemTask)) {
                    int itemsRemoved = (int) Math.min(data.getProgress(itemTask), count);
                    if (!simulate) {
                        data.addProgress(itemTask, -itemsRemoved);
                    }
                    return itemTask.getItemStack().copyWithCount(itemsRemoved);
                }
            }
            return ItemStack.EMPTY;
        }

        @Override
        public int getSlotLimit(int slot) {
            return getTask() instanceof ItemTask itemTask ? itemTask.getItemStack().getMaxStackSize() : 0;
        }

        @Override
        public boolean isItemValid(int slot, @NotNull ItemStack stack) {
            return slot == 1 && getTask() instanceof ItemTask itemTask && itemTask.test(stack);
        }
    }

    private class TaskFluidHandler implements IFluidHandler {
        @Override
        public int getTanks() {
            return 1;
        }

        @NotNull
        @Override
        public FluidStack getFluidInTank(int tank) {
            return tank == 0 && getTask() instanceof FluidTask fluidTask ?
                    new FluidStack(fluidTask.getFluid(), (int) getCachedTeamData().getProgress(fluidTask)) :
                    FluidStack.EMPTY;
        }

        @Override
        public int getTankCapacity(int tank) {
            return tank == 0 && getTask() instanceof FluidTask fluidTask ?
                    (int) fluidTask.getMaxProgress() :
                    0;
        }

        @Override
        public boolean isFluidValid(int tank, @NotNull FluidStack fluidStack) {
            if (tank != 0 || !(getTask() instanceof FluidTask fluidTask)) {
                return false;
            }
            // amount is not important here
            FluidStack taskFluidStack = new FluidStack(Holder.direct(fluidTask.getFluid()), 1000, fluidTask.getFluidDataComponentPatch());
            return FluidStack.isSameFluidSameComponents(taskFluidStack, fluidStack);
        }

        @Override
        public int fill(FluidStack fluidStack, FluidAction fluidAction) {
            if (getTask() instanceof FluidTask fluidTask && isFluidValid(0, fluidStack)) {
                TeamData data = getCachedTeamData();
                if (data != null && data.canStartTasks(fluidTask.getQuest()) && !data.isCompleted(fluidTask)) {
                    long space = fluidTask.getMaxProgress() - data.getProgress(fluidTask);
                    long toAdd = Math.min(fluidStack.getAmount(), space);
                    if (fluidAction.execute()) {
                        data.addProgress(fluidTask, Math.min(fluidStack.getAmount(), toAdd));
                    }
                    return (int) toAdd;
                }
            }
            return 0;
        }

        @NotNull
        @Override
        public FluidStack drain(FluidStack fluidStack, FluidAction fluidAction) {
            return getTask() instanceof FluidTask task && fluidStack.getFluid() == task.getFluid() ?
                    drain(fluidStack.getAmount(), fluidAction) :
                    FluidStack.EMPTY;
        }

        @NotNull
        @Override
        public FluidStack drain(int maxDrain, FluidAction fluidAction) {
            if (getTask() instanceof FluidTask task) {
                TeamData data = getCachedTeamData();
                if (data != null && data.canStartTasks(task.getQuest()) && !data.isCompleted(task)) {
                    long toTake = Math.min(maxDrain, data.getProgress(task));
                    if (fluidAction.execute()) {
                        data.addProgress(task, -toTake);
                    }
                    FluidStack result = new FluidStack(task.getFluid(), (int) toTake);
                    result.applyComponents(task.getFluidDataComponents());
//                    if (task.getFluidDataComponents() != null) result.setTag(task.getFluidDataComponents().copy());
                    return result;
                }
            }
            return FluidStack.EMPTY;
        }
    }

    private class TaskEnergyHandler implements IEnergyStorage {
        @Override
        public int receiveEnergy(int amount, boolean simulate) {
            if (getTask() instanceof ForgeEnergyTask energyTask) {
                TeamData data = getCachedTeamData();
                if (data != null && data.canStartTasks(energyTask.getQuest()) && !data.isCompleted(energyTask)) {
                    long space = energyTask.getMaxProgress() - data.getProgress(energyTask);
                    long toAdd = Math.min(energyTask.getMaxInput(), Math.min(amount, space));
                    if (!simulate) {
                        data.addProgress(energyTask, toAdd);
                    }
                    return (int) toAdd;
                }
            }
            return 0;
        }

        @Override
        public int extractEnergy(int amount, boolean simulate) {
            return 0;
        }

        @Override
        public int getEnergyStored() {
            return getTask() instanceof ForgeEnergyTask energyTask ? (int) getCachedTeamData().getProgress(energyTask) : 0;
        }

        @Override
        public int getMaxEnergyStored() {
            return getTask() instanceof ForgeEnergyTask energyTask ? (int) energyTask.getValue() : 0;
        }

        @Override
        public boolean canExtract() {
            return false;
        }

        @Override
        public boolean canReceive() {
            return true;
        }
    }
}

